import{_ as a}from"./chunks/more-horizontal.C1CblXWl.js";import{_ as t}from"./chunks/eye.BRl0ZGNz.js";import{_ as o,c as l,o as r,ag as s}from"./chunks/framework.DZ_cNctr.js";const m=JSON.parse('{"title":"Labels — Find Nuclei Viewer","description":"Load and display segmentation masks on OME-Zarr images. Add embedded labels, local folders, or remote URLs. Control opacity, fill/contour rendering, coloring, grouping, tags, notes, and key-value metadata.","frontmatter":{"title":"Labels — Find Nuclei Viewer","description":"Load and display segmentation masks on OME-Zarr images. Add embedded labels, local folders, or remote URLs. Control opacity, fill/contour rendering, coloring, grouping, tags, notes, and key-value metadata."},"headers":[],"relativePath":"guides/labels.md","filePath":"guides/labels.md"}'),n={name:"guides/labels.md"};function i(d,e,h,c,p,u){return r(),l("div",null,[...e[0]||(e[0]=[s('<h1 id="labels" tabindex="-1">Labels <a class="header-anchor" href="#labels" aria-label="Permalink to &quot;Labels&quot;">​</a></h1><p>A <strong>label</strong> is a segmentation mask — one integer per pixel, where each integer is an object ID. Labels live alongside your image and render as a coloured overlay so you can see what was detected by your segmentation tool (CellProfiler, Cellpose, StarDist, InstanSeg, and anything else that writes OME-Zarr or bare Zarr masks).</p><p>This guide covers the foundational workflow: load labels, control how they look, organise them, attach metadata. For per-object coloring by measurement CSVs (heatmap, category, phenotypes), see the <a href="./analytics-phenotyping.html">Analytics &amp; Phenotyping guide</a>.</p><div class="fn-screenshot-placeholder"><span class="fn-sp-label">Screenshot</span> <code>labels-overview.png</code> — Wide shot: Labels tab open, list showing a few embedded labels + one external EXT label, image with a segmentation overlay visible in colour. </div><h2 id="loading-labels" tabindex="-1">Loading labels <a class="header-anchor" href="#loading-labels" aria-label="Permalink to &quot;Loading labels&quot;">​</a></h2><p>The <strong>Labels tab</strong> has three buttons at the top:</p><table tabindex="0"><thead><tr><th>Button</th><th>What it does</th></tr></thead><tbody><tr><td><strong>Add Local</strong></td><td>Pick a folder on your disk that contains a Zarr label array. Chrome / Edge only.</td></tr><tr><td><strong>Add URL</strong></td><td>Paste a URL pointing at a Zarr label array. Works in any browser.</td></tr><tr><td><img src="'+a+'" class="fn-icon" alt="refresh"> <strong>Refresh</strong></td><td>Re-scan the current image&#39;s OME-Zarr for embedded labels. Useful if a segmentation job has just written a new label and you don&#39;t want to reload the whole image.</td></tr></tbody></table><div class="fn-screenshot-placeholder"><span class="fn-sp-label">Screenshot</span> <code>labels-toolbar.png</code> — Top of Labels tab with Add Local / Add URL / Refresh buttons and the Filter / Search row below. </div><h3 id="embedded-labels" tabindex="-1">Embedded labels <a class="header-anchor" href="#embedded-labels" aria-label="Permalink to &quot;Embedded labels&quot;">​</a></h3><p>Labels written inside your OME-Zarr (under the <code>/labels/</code> group, per the OME-NGFF spec) are discovered automatically on image load. No clicking required — they appear in the <strong>Embedded</strong> group in the list.</p><h3 id="local-folders-add-local" tabindex="-1">Local folders (Add Local) <a class="header-anchor" href="#local-folders-add-local" aria-label="Permalink to &quot;Local folders (Add Local)&quot;">​</a></h3><p>Click <strong>Add Local</strong>, pick any folder containing a Zarr label. The folder stays on your disk — the viewer reads it directly via the File System Access API. Use this when you&#39;ve run a segmentation tool that wrote a Zarr mask next to (but not inside) your image.</p><h3 id="remote-urls-add-url" tabindex="-1">Remote URLs (Add URL) <a class="header-anchor" href="#remote-urls-add-url" aria-label="Permalink to &quot;Remote URLs (Add URL)&quot;">​</a></h3><p>Click <strong>Add URL</strong> and paste the URL of a Zarr label array. Works from any storage that serves HTTP range requests and the right CORS headers: S3, Cloudflare R2, GCS, Azure Blob, an on-premise nginx, a data server running locally. See the <a href="./data-server.html">Data Server guide</a> for hosting your own.</p><p>External labels (not embedded in the image&#39;s OME-Zarr) show an <strong>EXT</strong> badge in the list so you can tell them apart from the embedded ones.</p><h2 id="label-rows" tabindex="-1">Label rows <a class="header-anchor" href="#label-rows" aria-label="Permalink to &quot;Label rows&quot;">​</a></h2><p>Every label renders as a row with the essentials on a single line:</p><ul><li><img src="'+t+'" class="fn-icon" alt="visibility"> toggle visibility</li><li>Color swatch — click to open the style popover</li><li>Label name — double-click to rename</li><li>Filter count badge — appears when analytics is loaded, showing how many filters are active</li><li><strong>EXT</strong> badge — only on external labels</li></ul><p>Click the row to expand its detail panel below, where you&#39;ll find Metadata (Source / Notes / Tags / Key-values) and — if analytics is loaded — the Analytics section.</p><div class="fn-screenshot-placeholder"><span class="fn-sp-label">Screenshot</span> <code>labels-row-expanded.png</code> — A label row expanded, showing the Metadata section (Source, Notes textarea, Tags chips, Key-values mini-table). </div><h2 id="style-—-solid-random-or-per-object" tabindex="-1">Style — solid, random, or per-object <a class="header-anchor" href="#style-—-solid-random-or-per-object" aria-label="Permalink to &quot;Style — solid, random, or per-object&quot;">​</a></h2><p>Click the color swatch on a label row to open the <strong>style popover</strong>. It holds the display controls for that label:</p><div class="fn-screenshot-placeholder"><span class="fn-sp-label">Screenshot</span> <code>labels-style-popover.png</code> — The style popover open showing the Solid / Random tabs (Heatmap / Category are grayed out when no CSV is loaded), Opacity slider, Render (FILL / CONTOUR) toggles, Presets color grid. </div><table tabindex="0"><thead><tr><th>Control</th><th>Effect</th></tr></thead><tbody><tr><td><strong>Solid</strong></td><td>Every object in the label shares a single colour (the one you pick below). Default for newly loaded labels.</td></tr><tr><td><strong>Random</strong></td><td>Each object gets a colour hashed from its ID — different objects look different, same object gets the same colour across reloads. Useful for visually distinguishing neighbouring cells without a segmentation-quality judgement.</td></tr><tr><td><strong>Heatmap</strong></td><td>Colour by a numeric column. Requires an analytics CSV — see the <a href="./analytics-phenotyping.html">Analytics guide</a>.</td></tr><tr><td><strong>Category</strong></td><td>Colour by a string column. Requires an analytics CSV.</td></tr><tr><td><strong>Opacity slider</strong></td><td>Blends the label layer with the image underneath. 0 hides the label; 1 makes it fully opaque.</td></tr><tr><td><strong>FILL / CONTOUR</strong></td><td>Two independent toggles for polygon labels. Fill paints the interior; contour draws a 1-px outline. Turn fill off for &quot;outlines-only&quot; view — useful when you want to see the image through your segmentation.</td></tr><tr><td><strong>Presets grid</strong></td><td>16 curated colours — RGB primaries on top, muted variants on the bottom row. One click applies.</td></tr><tr><td><strong>Hex / RGB inputs</strong></td><td>Type <code>#FF00AA</code> or type the three RGB values directly. Synced bidirectionally.</td></tr><tr><td><strong>More colors…</strong></td><td>Opens the OS-native picker for any colour + eyedropper (Chrome / Edge).</td></tr></tbody></table><h2 id="global-fill-contour" tabindex="-1">Global fill / contour <a class="header-anchor" href="#global-fill-contour" aria-label="Permalink to &quot;Global fill / contour&quot;">​</a></h2><p>The kebab menu on the Annotations toolbar holds four global actions that also affect labels&#39; polygons (conceptually similar — they live on the Annotations tab because they&#39;re bulk-visibility operations):</p><ul><li><strong>Show all</strong> / <strong>Hide all</strong> — toggle the eye icon for every label at once</li><li><strong>Turn fill on / off</strong> — apply to every label</li><li><strong>Turn contour on / off</strong> — apply to every label</li></ul><p>For per-label fill/contour, use the style popover above.</p><h2 id="grouping" tabindex="-1">Grouping <a class="header-anchor" href="#grouping" aria-label="Permalink to &quot;Grouping&quot;">​</a></h2><p>The Labels list groups by <strong>Source</strong> by default — embedded labels under &quot;Embedded&quot;, each external label gets its own group header. You can switch to <strong>Group By key-value</strong> using the toolbar:</p><div class="fn-screenshot-placeholder"><span class="fn-sp-label">Screenshot</span> <code>labels-group-by-menu.png</code> — Group By dropdown open, showing a list of available key-value fields (class, grade, etc.). </div><p>Grouping by a key-value field is useful when you&#39;ve added consistent metadata across labels — e.g., <code>tissue: tumor</code> on some labels and <code>tissue: stroma</code> on others. The list then organises by that field instead of by source.</p><p>Drag the grip handle on the left of each group header to <strong>reorder groups</strong>. The group order also controls rendering z-order on the canvas — later groups draw on top.</p><h2 id="search-and-filter" tabindex="-1">Search and filter <a class="header-anchor" href="#search-and-filter" aria-label="Permalink to &quot;Search and filter&quot;">​</a></h2><p>The toolbar row has a <strong>Filter</strong> dropdown and a <strong>Search</strong> input:</p><ul><li><strong>Filter</strong>: show All / only Visible / only Hidden labels.</li><li><strong>Search</strong>: type part of a label name, tag, or metadata value. The list narrows to matches live.</li></ul><div class="fn-screenshot-placeholder"><span class="fn-sp-label">Screenshot</span> <code>labels-search.png</code> — Search input active, list narrowed to labels whose name contains &quot;nuclei&quot;. </div><h2 id="metadata-—-source-notes-tags-key-values" tabindex="-1">Metadata — Source, Notes, Tags, Key-values <a class="header-anchor" href="#metadata-—-source-notes-tags-key-values" aria-label="Permalink to &quot;Metadata — Source, Notes, Tags, Key-values&quot;">​</a></h2><p>Expand a label&#39;s row and open the <strong>METADATA</strong> section. Four fields live here:</p><ul><li><strong>Source</strong> — read-only, shows where the label came from (embedded path, local folder, URL).</li><li><strong>Notes</strong> — free-form text. &quot;Run 2 from Cellpose, threshold 0.65.&quot;</li><li><strong>Tags</strong> — short chips you can add / remove. &quot;validated&quot;, &quot;needs-review&quot;.</li><li><strong>Key-values</strong> — structured <code>key: value</code> rows. Add <code>class: tumor</code> here, then switch to <strong>Group By: class</strong> on the toolbar and your labels organise by that field.</li></ul><div class="fn-screenshot-placeholder"><span class="fn-sp-label">Screenshot</span> <code>labels-metadata.png</code> — Expanded METADATA section showing Source, Notes textarea with example text, three tags, and a couple of key-values. </div><p>Metadata persists to IndexedDB per-label and survives reloads.</p><h2 id="hcs-plates" tabindex="-1">HCS plates <a class="header-anchor" href="#hcs-plates" aria-label="Permalink to &quot;HCS plates&quot;">​</a></h2><p>When you open a high-content-screening plate, labels work the same way but apply at the plate level — a label named <code>nuclei</code> is discovered on every populated well and renders consistently across all fields. See the <a href="./hcs-plates.html">HCS Plates guide</a> for plate-specific controls (well navigation, field grid, plate overview).</p><h2 id="persistence" tabindex="-1">Persistence <a class="header-anchor" href="#persistence" aria-label="Permalink to &quot;Persistence&quot;">​</a></h2><p>Everything you do in the Labels tab persists to your browser&#39;s IndexedDB, keyed by the image&#39;s URL or local folder handle:</p><ul><li>Visibility, colour mode, opacity, fill/contour state</li><li>Notes, tags, key-values</li><li>Which labels you&#39;ve added external / URL-based</li><li>Current group-by mode</li></ul><p>Reload the page, reopen the image — your label configuration is still there. The URL query string captures viewport state (zoom, center, active channels) but <strong>not</strong> label configuration; that lives in the browser locally.</p><h2 id="mobile" tabindex="-1">Mobile <a class="header-anchor" href="#mobile" aria-label="Permalink to &quot;Mobile&quot;">​</a></h2><p>On phone viewports the Labels tab shows the row list and basic visibility toggles, but <strong>heatmap / category / phenotype coloring tabs are disabled</strong> because per-object coloring needs an analytics CSV — and the File System Access API required to pick a CSV doesn&#39;t exist on phones. Tablets show the full desktop UI.</p><h2 id="next-steps" tabindex="-1">Next steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next steps&quot;">​</a></h2><ul><li>Want to colour cells by area, intensity, or any measurement? <a href="./analytics-phenotyping.html">Analytics &amp; Phenotyping</a>.</li><li>Drawing your own regions (not from a segmentation mask)? <a href="./annotations.html">Annotations</a>.</li><li>Sharing your view with a reviewer? <a href="./sharing.html">Sharing Views</a>.</li><li>Hosting your own label data? <a href="./data-server.html">Data Server</a>.</li></ul>',52)])])}const f=o(n,[["render",i]]);export{m as __pageData,f as default};
